-- Daily challenges for 2026-11-02: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-11-02. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('making-chores-feel-lighter', 'Making Chores Feel Lighter', 'For anyone who feels buried under laundry, dishes and the chores that never seem to end. Each day is one small way to make housework lighter, from sharing the load and pairing chores with music to doing a little less and noticing the care in it.', 'Home', 365, array['Habits', 'Stress', 'Family']::text[], 1, '2026-11-02T17:00:00+00:00'::timestamptz),
  ('staying-close-to-the-older-people-you-love', 'Staying Close to the Older People You Love', 'For anyone with a parent, grandparent, aunt, uncle or older friend they want to stay close to. Each day is one small way to connect, from a phone call or a shared meal to asking for their stories and making visits easier.', 'Connection', 365, array['Family', 'Relationships']::text[], 1, '2026-11-02T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('making-chores-feel-lighter', 'staying-close-to-the-older-people-you-love');

